<script setup>import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({email:'',password:'',remember:false,turnstile_token:''});const submit=()=>{if(form.processing)return;form.post('/login',{onFinish:()=>{form.reset('password');form.turnstile_token='';turnstile.value?.reset()}})};</script>
<template><Head title="Masuk"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Selamat datang</p><h1>Masuk LFAMILIA</h1><p>Masuk untuk melihat saldo, pesanan, membership, tiket, dan profilmu.</p><p v-if="page.props.errors?.google" role="alert" class="mb-3 text-xs text-red-300">{{page.props.errors.google}}</p><p v-if="page.props.status" role="status" class="mb-3 text-xs text-[#cfff72]">{{page.props.status}}</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">Email<input v-model="form.email" type="email" name="email" autocomplete="username" placeholder="Masukkan email" :aria-invalid="Boolean(form.errors.email)" required><span v-if="form.errors.email" role="alert" class="block mt-1 text-red-300">{{form.errors.email}}</span></label><label class="text-[10px] font-semibold text-white/70">Kata sandi<input v-model="form.password" type="password" name="password" autocomplete="current-password" placeholder="Masukkan kata sandi" :aria-invalid="Boolean(form.errors.password)" required><span v-if="form.errors.password" role="alert" class="block mt-1 text-red-300">{{form.errors.password}}</span></label><label class="flex items-center gap-2 text-xs"><input v-model="form.remember" type="checkbox" name="remember"> Ingat saya</label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><p v-if="form.errors.turnstile_token" role="alert" class="text-xs text-red-300">{{form.errors.turnstile_token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Memproses…':'Masuk'}}</button><a href="/auth/google/redirect" class="lf-secondary w-full">Masuk dengan Google</a></div><div class="lf-auth-links"><Link href="/forgot-password">Lupa password?</Link><Link href="/register">Daftar</Link></div></form></main></CustomerShell></template>